/* Stub for miniz's generated export header.
 * miniz's upstream build generates this via CMake GenerateExportHeader when
 * producing a shared library. We link miniz statically into `spectral`, so
 * every MINIZ_EXPORT symbol simply has no visibility annotation.
 */
#ifndef MINIZ_EXPORT_H
#define MINIZ_EXPORT_H

#define MINIZ_EXPORT
#define MINIZ_NO_EXPORT
#define MINIZ_DEPRECATED

#endif /* MINIZ_EXPORT_H */
